// 页面加载完成后修改搜索区域
(function() {
  let isModified = false;

  function modifySearchArea() {
    if (isModified) return;

    // 查找搜索输入框 - 通过placeholder或类名
    let searchInput = document.querySelector('input[placeholder*="搜"], input[placeholder*="找"], .el-input__inner');
    if (!searchInput) return;

    // 找到el-input__wrapper - 这是输入框的包装器
    const inputWrapper = searchInput.closest('.el-input__wrapper');
    if (!inputWrapper) return;

    // 将 input 替换为 textarea 以支持多行文本
    if (searchInput.tagName.toLowerCase() === 'input') {
      const textarea = document.createElement('textarea');
      textarea.className = searchInput.className;
      textarea.placeholder = searchInput.placeholder;
      textarea.id = searchInput.id;
      textarea.setAttribute('data-original-placeholder', searchInput.getAttribute('data-original-placeholder') || searchInput.placeholder);
      textarea.setAttribute('autocomplete', 'off');
      textarea.setAttribute('tabindex', '0');
      textarea.style.resize = 'none';
      textarea.style.overflow = 'auto';
      textarea.style.minHeight = '80px';
      textarea.style.height = '80px';
      searchInput.parentNode.replaceChild(textarea, searchInput);
      searchInput = textarea;
    }

    // 找到最外层的容器
    let outerContainer = searchInput.closest('.el-input-group');
    if (!outerContainer) {
      outerContainer = searchInput.closest('.el-input');
    }
    if (!outerContainer) return;

    // 找到flex-row容器
    let flexContainer = outerContainer.closest('.flex-row, .items-center');
    if (!flexContainer) {
      flexContainer = outerContainer.parentElement;
    }
    if (!flexContainer) return;

    // 检查是否已经添加过底部按钮
    if (inputWrapper.querySelector('.search-bottom-actions')) return;

    // 给外层容器添加样式类
    flexContainer.classList.add('search-entry-container');

    // 清除可能干扰的内联样式
    flexContainer.style.width = '';
    flexContainer.style.maxWidth = '';
    flexContainer.style.margin = '';
    flexContainer.style.left = '';
    flexContainer.style.right = '';
    flexContainer.style.transform = '';

    // 查找搜索按钮（在el-input-group__append中）
    const searchBtnContainer = outerContainer.querySelector('.el-input-group__append');
    let searchBtn = null;
    if (searchBtnContainer) {
      searchBtn = searchBtnContainer.querySelector('.search-btn, .el-button');
      // 隐藏原始的append容器
      searchBtnContainer.style.display = 'none';
    }

    // 创建搜索按钮（如果找到了就克隆，否则创建新的）
    let searchBtnHtml = '';
    if (searchBtn) {
      // 克隆搜索按钮
      const clonedBtn = searchBtn.cloneNode(true);
      clonedBtn.removeAttribute('disabled');
      clonedBtn.classList.remove('is-disabled');
      clonedBtn.setAttribute('onclick', 'handleSearch()');
      // 替换为发送图标
      clonedBtn.innerHTML = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"></path></svg>';
      const btnContainer = document.createElement('div');
      btnContainer.appendChild(clonedBtn);
      searchBtnHtml = btnContainer.innerHTML;
    } else {
      // 创建默认搜索按钮
      searchBtnHtml = `
        <button class="el-button el-button--default is-circle search-btn-internal" onclick="handleSearch()" title="搜索">
            <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"></path></svg>
        </button>
      `;
    }

    // 创建搜索按钮容器（放在inputWrapper内部右上角）
    const searchBtnWrapper = document.createElement('div');
    searchBtnWrapper.className = 'search-btn-wrapper';
    searchBtnWrapper.innerHTML = searchBtnHtml;
    inputWrapper.appendChild(searchBtnWrapper);
    // 添加上传附件按钮（放在search-btn-wrapper同级前）
    var uploadBtn = document.createElement('button');
    uploadBtn.className = 'upload-attach-btn';
    uploadBtn.setAttribute('type', 'button');
    uploadBtn.title = '上传文件';
    uploadBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5.5498 9.75V5H6.9502V9.75C6.9502 10.3299 7.4201 10.7998 8 10.7998C8.5799 10.7998 9.0498 10.3299 9.0498 9.75V4.5C9.0498 2.9536 7.7964 1.7002 6.25 1.7002C4.7036 1.7002 3.4502 2.9536 3.4502 4.5V9.75C3.4502 12.2629 5.4871 14.2998 8 14.2998C10.5129 14.2998 12.5498 12.2629 12.5498 9.75V4H13.9502V9.75C13.9502 13.0361 11.2861 15.7002 8 15.7002C4.71391 15.7002 2.0498 13.0361 2.0498 9.75V4.5C2.04981 2.1804 3.9304 0.299806 6.25 0.299805C8.5696 0.299805 10.4502 2.1804 10.4502 4.5V9.75C10.4502 11.1031 9.3531 12.2002 8 12.2002C6.6469 12.2002 5.5498 11.1031 5.5498 9.75Z" fill="currentColor"></path></svg>';
    uploadBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      if (window._triggerFileUpload) window._triggerFileUpload();
    });
    inputWrapper.insertBefore(uploadBtn, searchBtnWrapper);

    // 创建底部按钮区域 - 插入到inputWrapper内部
    const bottomActions = document.createElement('div');
    bottomActions.className = 'search-bottom-actions';
    bottomActions.innerHTML = `
      <button class="history-btn" onclick="location.href='./chat.html?mode=last-session'" title="历史记录">
        <svg viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" width="14" height="14" fill="currentColor">
          <path d="M729.6 499.2c127.488 0 230.4 102.912 230.4 230.4s-102.912 230.4-230.4 230.4-230.4-102.912-230.4-230.4 102.912-230.4 230.4-230.4z m0 409.6c98.816 0 179.2-80.384 179.2-179.2s-80.384-179.2-179.2-179.2-179.2 80.384-179.2 179.2 80.384 179.2 179.2 179.2z m87.04-204.8c8.704 0 15.36 7.168 15.36 15.36v19.968c0 8.704-7.168 15.36-15.36 15.36h-96.768c-8.704 0-15.36-7.168-15.36-15.36v-122.368c0-8.704 7.168-15.36 15.36-15.36h19.968c8.704 0 15.36 7.168 15.36 15.36v87.04h61.44z"></path>
          <path d="M924.672 506.88l10.24 0.512c13.312 1.024 25.088-9.728 25.088-23.04 0-201.216-200.704-364.032-448-364.032s-448 163.328-447.488 363.52c0 83.456 34.816 159.744 92.672 221.184-26.112 68.608-80.384 127.488-81.408 128-11.776 12.288-14.848 29.696-8.192 45.568 6.656 15.872 22.016 25.6 38.912 25.6 107.52 0 192.512-45.056 243.2-80.896 22.016 7.168 45.568 12.8 69.12 16.896 13.824 2.56 27.648-6.656 29.696-20.992l1.024-4.608c2.56-13.824-7.168-26.624-20.992-29.184-20.992-3.584-41.472-8.704-61.952-15.36l-26.624-8.192-22.528 15.872c-40.448 28.16-102.4 61.44-179.712 69.12 20.992-26.624 51.712-70.656 71.168-121.856l12.288-32.768-24.064-25.6c-50.688-53.248-77.312-116.736-77.312-182.272 0-169.472 176.128-307.712 392.192-307.712s392.192 138.752 392.192 308.224c0 11.776 8.704 21.504 20.48 22.016z"></path>
        </svg>
      </button>
      <button class="action-btn" onclick="handleTranslate()" title="专家级翻译智能体，支持多种语言">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
          <path d="M5 8l6 6"/>
          <path d="M4 14l6-6 3-3"/>
          <path d="M2 5h12"/>
          <path d="M7 2h1"/>
          <path d="M22 22l-5-10-5 10"/>
          <path d="M14 18h6"/>
        </svg>
        <span>象胥翻译</span>
      </button>
      <button class="action-btn" onclick="toggleSimpleSearchMode()" title="输入关键词进行简单快捷检索">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="11" cy="11" r="8"/>
          <path d="M21 21l-4.35-4.35"/>
          <line x1="8" y1="11" x2="14" y2="11"/>
        </svg>
        <span>简单搜索</span>
      </button>
    `;

    // 将按钮插入到inputWrapper内部
    inputWrapper.appendChild(bottomActions);

    // 移动AI阅读助手和知识库按钮到搜索区域下方
    moveNavButtons();

    // 添加 ready 类显示搜索区域
    const searchView = document.querySelector('.search-entry-view');
    if (searchView) {
      searchView.classList.add('search-area-ready');
    }

    isModified = true;
    console.log('搜索区域修改完成');

    // 初始设置按钮禁用态 + 启动输入监听（问答模式）
    updateSendButtonState();
    initInputMonitoring();
  }

  function moveNavButtons() {
    var navContainer = document.querySelector('.other-nav-entry-view');
    var searchView = document.querySelector('.search-entry-view');
    if (!navContainer || !searchView) return;
    if (navContainer.classList.contains('moved')) return;

    // 保留原始 Vue 按钮引用（用于转发点击事件）
    var origBtns = navContainer.querySelectorAll('.flex-row > *');
    var origAiBtn = null, origKbBtn = null;
    origBtns.forEach(function(b) {
      var t = b.textContent.trim();
      if (t.indexOf('AI') !== -1 || t.indexOf('阅读') !== -1) origAiBtn = b;
      else origKbBtn = b;
