  // ========== 每日简报区域 ==========
  function insertDailyBriefing(searchView) {
    if (!searchView || !searchView.parentNode) return;
    if (document.querySelector('.ai-daily-module')) return;

    // ---------- 模拟日报数据集 ----------
    var reportsDB = {
        "2026-06-12": {
            fullDate: "06/12",
            weekday: "周五",
