  function initLitStatsPanel() {
    if (_litStatsStarted) return;
    // 找到搜索输入框
    const searchContainer = document.querySelector('.search-entry-container');
    if (!searchContainer) return;
    // 父容器：搜索视图或 home wrapper
    const parent = searchContainer.parentNode;
    if (!parent) return;

    const panel = buildLitStatsPanel();

    // 找到 MossLib 图片
    let imgEl = null;
    let cursor = searchContainer.previousElementSibling;
    while (cursor) {
      if (cursor.tagName === 'IMG'
        || /logo|mosslib|banner|hero|cover/i.test(cursor.className || '')
        || cursor.querySelector('img')) {
        imgEl = cursor.tagName === 'IMG' ? cursor : cursor.querySelector('img');
        break;
      }
      cursor = cursor.previousElementSibling;
    }

    if (imgEl) {
      // 用 flex row 容器包裹 img 和列表，列表在右侧纵向排列
      const wrapper = document.createElement('div');
      wrapper.className = 'lit-stats-wrapper';
      const imgParent = imgEl.parentNode;
      imgParent.insertBefore(wrapper, imgEl);
      wrapper.appendChild(imgEl);
      wrapper.appendChild(panel);
    } else {
      const parent = searchContainer.parentNode;
      if (parent) parent.insertBefore(panel, searchContainer);
    }

    _litStatsStarted = true;

    // 触发数字滚动动画（带轻微错峰效果）
    const numbers = panel.querySelectorAll('.lit-stats-number');
    numbers.forEach(function(numEl, idx) {
      const target = parseInt(numEl.getAttribute('data-target'), 10);
      if (isNaN(target)) return;
      const valueWrap = numEl.closest('.lit-stats-value');
      if (valueWrap) {
        valueWrap.classList.add('is-animating');
        setTimeout(function() { valueWrap.classList.remove('is-animating'); }, 700);
      }
      setTimeout(function() {
        animateLitCount(numEl, target, 1600 + idx * 200);
      }, 200 + idx * 220);
    });
  }

