  window.handleTranslateSend = function() {
    console.log('翻译发送 clicked');

    // 检查是否可发送
    var btn = document.querySelector('.search-btn-wrapper button, .search-btn-internal');
    if ((btn && btn.classList.contains('disabled')) || window._docParsing) return;

    // 获取目标语言
    var targetLangSelect = document.querySelector('.search-entry-container.translate-mode .lang-select-small');
    var targetLang = targetLangSelect ? targetLangSelect.value || '中文' : '中文';

    // 检查是否有文档上传
    const docInfoArea = document.querySelector('.document-info-area');
    if (docInfoArea) {
      // 获取文档信息
      const docName = docInfoArea.querySelector('.document-name')?.textContent || '';
      const docSize = docInfoArea.querySelector('.document-size')?.textContent || '';

      // 构建跳转URL，传递文档翻译参数
      const params = new URLSearchParams();
      params.set('mode', 'doc-translate');
      params.set('docName', docName);
      params.set('docSize', docSize);
      params.set('targetLang', targetLang);

      window.location.href = './chat.html?' + params.toString();
      return;
    }

    // 普通文本翻译
    var textarea = document.querySelector('.search-entry-container textarea');
    var text = textarea ? textarea.value.trim() : '';
    if (!text) {
      textarea = document.querySelector('.translate-textarea');
      text = textarea ? textarea.value.trim() : '';
    }
    if (!text) {
      var inputArea = document.querySelector('.el-input__inner');
      text = inputArea ? inputArea.value.trim() : '';
    }
    if (text) {
      var params = new URLSearchParams();
      params.set('mode', 'translate');
      params.set('text', text);
      params.set('targetLang', targetLang);
      window.location.href = './chat.html?' + params.toString();
    } else {
      alert('请输入要翻译的文本');
    }
  };

  window.handleSearch = function() {
    console.log('搜索 clicked');
    var btn = document.querySelector('.search-btn-wrapper button, .search-btn-internal');
    if (btn && btn.classList.contains('disabled')) return;
    var container = document.querySelector('.search-entry-container');
    if (!container) return;
    var input = container.querySelector('textarea, input.el-input__inner');
    var text = input ? input.value : '';
    if (text) {
      // 跳转到chat.html页面，并传递搜索内容
      window.location.href = './chat.html?q=' + encodeURIComponent(text);
    } else {
      alert('请输入搜索内容');
    }
  };

  // 文档翻译 - 打开文件选择器（仅支持Word文件）
  window.handleDocumentTranslate = function() {
    // 创建隐藏的文件输入元素
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    fileInput.style.display = 'none';

    // 监听文件选择事件
    fileInput.addEventListener('change', function(e) {
      const file = e.target.files[0];
      if (file) {
        const isWordFile = file.name.toLowerCase().endsWith('.doc') || 
                          file.name.toLowerCase().endsWith('.docx') ||
                          file.type === 'application/msword' ||
                          file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
        if (isWordFile) {
          console.log('选择的Word文件:', file.name);
          // 显示文件信息在输入框区域
          showDocumentInfo(file);
        } else {
          alert('请选择Word格式的文件（.doc 或 .docx）');
        }
      }
      // 移除临时创建的元素
      document.body.removeChild(fileInput);
    });

    document.body.appendChild(fileInput);
    fileInput.click();
  };

