  // 删除文档，恢复到初始状态
  window.deleteDocument = function() {
    const searchContainer = document.querySelector('.search-entry-container');
    const inputWrapper = document.querySelector('.search-entry-container .el-input__wrapper');
    if (!inputWrapper) return;

    // 移除文档信息区域
    const docInfoArea = inputWrapper.querySelector('.document-info-area');
    if (docInfoArea) {
      docInfoArea.remove();
    }

    // 恢复textarea显示
    const textarea = inputWrapper.querySelector('textarea');
    if (textarea) {
      textarea.style.display = '';
    }
    window._docParsing = false;
    updateSendButtonState();
  };

  // 更新发送按钮状态（问答/翻译模式通用）
  function updateSendButtonState() {
    var container = document.querySelector('.search-entry-container');
    if (!container) return;
    var btn = container.querySelector('.search-btn-wrapper button, .search-btn-internal');
    if (!btn) return;

    var isTranslate = container.classList.contains('translate-mode');

    // 文档解析中 → 禁用（仅翻译模式）
    if (isTranslate && window._docParsing) {
      btn.classList.add('disabled');
      return;
    }

    // 获取输入文本（textarea 或 input）
    var textarea = container.querySelector('textarea, .el-input__inner');
    var text = textarea ? textarea.value.trim() : '';

    // 翻译模式：有文本或有文档 → 可用
    // 问答模式：有文本 → 可用
    var hasDoc = isTranslate && !!container.querySelector('.document-info-area');

    if (text || hasDoc || (window._getAttachments && window._getAttachments().length > 0)) {
      btn.classList.remove('disabled');
    } else {
      btn.classList.add('disabled');
    }
  }

  // 监听输入框变化，更新按钮状态
  function initInputMonitoring() {
    var container = document.querySelector('.search-entry-container');
    if (!container || container._inputMonitored) return;
    container._inputMonitored = true;

    container.addEventListener('input', function(e) {
      if (e.target.matches('textarea, .el-input__inner, .el-textarea__inner')) {
        setTimeout(updateSendButtonState, 10);
      }
    });

    container.addEventListener('compositionend', function(e) {
      if (e.target.matches('textarea, .el-input__inner, .el-textarea__inner')) {
        setTimeout(updateSendButtonState, 10);
      }
    });

    updateSendButtonState();
  }

