  // 定时修复搜索按钮图标（防止Vue重新渲染覆盖）
  setInterval(function() {
    const container = document.querySelector('.search-entry-container');
    if (!container) return;
    const isSimple = container.classList.contains('is-simple-search');
    const isTranslate = container.classList.contains('translate-mode');
    const btn = document.querySelector('.search-btn-wrapper button, .search-btn-internal');
    if (btn) {
      // 修复onclick - 根据模式设置正确的处理函数
      let expectedOnclick;
      if (isTranslate) {
        expectedOnclick = 'handleTranslateSend()';
      } else if (isSimple) {
        expectedOnclick = 'handleSimpleSearch()';
      } else {
        expectedOnclick = 'handleSearch()';
      }
      if (btn.getAttribute('onclick') !== expectedOnclick) {
        btn.setAttribute('onclick', expectedOnclick);
      }
      // 按钮图标固定为发送图标
      const expectedSvg = '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z"></path></svg>';
      const currentHtml = btn.innerHTML.replace(/\s+/g, ' ').trim();
      const targetHtml = expectedSvg.replace(/\s+/g, ' ').trim();
      if (currentHtml !== targetHtml) {
        btn.innerHTML = expectedSvg;
      }
    }
    // 同步发送按钮禁用状态（抗 Vue 重置）
    updateSendButtonState();
  }, 500);

