  // 将精准荐读原生结构挂载到「推荐」li 对应的 el-tab-pane 内容区
  function mountRecommendToPane() {
    var recommendLi = null;
    document.querySelectorAll('li.el-menu-item').forEach(function(li) {
      if (li.textContent.trim() === '推荐') recommendLi = li;
    });
    if (!recommendLi) return false;

    // 1) 通过 aria-controls 找到对应 el-tab-pane
    var pane = null;
    var controlsId = recommendLi.getAttribute('aria-controls');
    if (controlsId) pane = document.getElementById(controlsId);

    // 2) 退路：找当前可见的 el-tab-pane（且与"推荐" li 同级 el-tabs）
    if (!pane) {
      var panes = document.querySelectorAll('.el-tabs__content .el-tab-pane');
      for (var i = 0; i < panes.length; i++) {
        if (panes[i].offsetParent !== null) { pane = panes[i]; break; }
      }
    }
    if (!pane) return false;
    if (pane.__tdrMounted) return true;

    pane.innerHTML =
      '<div class="recommend-wrapper">' +
        '<div class="recommend-header">' +
          '<div class="recommend-title">精准荐读</div>' +
          '<div class="recommend-subtitle">基于您的订阅与研究行为</div>' +
        '</div>' +
        '<div class="subscription-section">' +
          '<div class="subscription-bar" id="subscriptionBar"></div>' +
          '<div class="subscription-manage" id="moreSubscriptionBtn">' +
            '<i class="ri-settings-3-line"></i> 订阅管理' +
          '</div>' +
        '</div>' +
        '<div class="card-grid" id="recommendGrid"></div>' +
      '</div>';
    pane.__tdrMounted = true;

    var manageBtn = document.getElementById('moreSubscriptionBtn');
    if (manageBtn) {
      manageBtn.addEventListener('click', function() {
        alert('订阅管理功能开发中：可在此处配置信源、关键词、主题、类型。');
      });
    }

    renderSubscriptionBar();
    renderRecommendGrid();
    return true;
  }

  // 追踪"推荐" li 的激活态：成为 is-active 时挂载精准荐读到对应 pane
  function watchRecommendActivation() {
    var recommendLi = null;
    document.querySelectorAll('li.el-menu-item').forEach(function(li) {
      if (li.textContent.trim() === '推荐') recommendLi = li;
    });
    if (!recommendLi) return false;
    if (recommendLi.__tdrWatchBound) return true;
    recommendLi.__tdrWatchBound = true;

    var tryMount = function() {
      if (!recommendLi.classList.contains('is-active')) return;
      if (mountRecommendToPane()) return;
      // pane 还没渲染：等一帧再试（最多 2s）
      var tries = 0;
      var iv = setInterval(function() {
        tries++;
        if (mountRecommendToPane() || tries > 40) clearInterval(iv);
      }, 50);
    };

    var mo = new MutationObserver(tryMount);
    mo.observe(recommendLi, { attributes: true, attributeFilter: ['class'] });

    // 兜底：首次主动尝试一次（处理"打开页面时推荐 li 已是激活态"的情况）
    tryMount();
    return true;
  }

  function startWatch() {
    if (watchRecommendActivation()) return;
    var tries = 0;
    var iv = setInterval(function() {
      tries++;
      if (watchRecommendActivation() || tries > 60) clearInterval(iv);
    }, 500);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startWatch);
  } else {
    setTimeout(startWatch, 100);
  }

  // 状态（沿用源文件 initRecommend 中的全局状态）
  let activeSubIds = [];

  // 渲染订阅栏（源文件 renderSubscriptionBar 原版）
  function renderSubscriptionBar() {
    const bar = document.getElementById('subscriptionBar');
    if (!bar) return;
    bar.innerHTML = '';

    const total = subscriptions.length;
    const showCount = 5;
    const subsToShow = subscriptions.slice(0, showCount);
    const hasMore = total > showCount;

    subsToShow.forEach(sub => bar.appendChild(createSubTagElement(sub)));

    if (hasMore) {
      const moreWrapper = document.createElement('div');
      moreWrapper.className = 'more-dropdown';
      moreWrapper.innerHTML =
        '<div class="sub-tag" id="moreSubTrigger">' +
          '<span class="sub-icon">📋</span> 更多 <span style="font-size:10px;">▼</span>' +
        '</div>' +
        '<div class="dropdown-content" id="moreDropdownContent"></div>';
      bar.appendChild(moreWrapper);

      const dropdownContent = moreWrapper.querySelector('#moreDropdownContent');
      subscriptions.slice(showCount).forEach(sub => dropdownContent.appendChild(createSubTagElement(sub)));

      const trigger = moreWrapper.querySelector('#moreSubTrigger');
      trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdownContent.classList.toggle('show');
      });
      document.addEventListener('click', (e) => {
        if (!moreWrapper.contains(e.target)) dropdownContent.classList.remove('show');
      });
    }
  }

  // 创建订阅标签元素（源文件 createSubTagElement 原版）
  function createSubTagElement(sub) {
    const tag = document.createElement('div');
    tag.className = 'sub-tag';
    if (activeSubIds.includes(sub.id)) tag.classList.add('active');

    const unreadCount = recommendItems.filter(item =>
      item.relatedSubIds && item.relatedSubIds.includes(sub.id)
    ).length;

    tag.innerHTML =
      '<span class="sub-avatar-icon"><i class="' + sub.avatarIcon + '"></i></span>' +
      '<span class="sub-title">' + sub.title + '</span>' +
      (unreadCount > 0 ? '<span class="sub-badge">' + unreadCount + '</span>' : '');

    tag.addEventListener('click', (e) => {
      e.stopPropagation();
      if (activeSubIds.includes(sub.id)) {
        activeSubIds = activeSubIds.filter(id => id !== sub.id);
      } else {
        activeSubIds.push(sub.id);
      }
      renderSubscriptionBar();
      renderRecommendGrid();
    });
    return tag;
  }

  // 渲染推荐卡片网格（源文件 renderRecommendGrid 原版）
  function renderRecommendGrid() {
    const grid = document.getElementById('recommendGrid');
    if (!grid) return;

    let filteredItems = recommendItems;
    if (activeSubIds.length > 0) {
      filteredItems = recommendItems.filter(item =>
        item.relatedSubIds && item.relatedSubIds.some(subId => activeSubIds.includes(subId))
      );
